SELECT id, symbol, side, status, quantity, entry_price, stop_loss, take_profit, exit_price, realized_pnl, signal_id, exit_signal_id, close_reason, opened_at, closed_at, TIMESTAMPDIFF(SECOND, opened_at, closed_at) AS hold_seconds, CASE WHEN entry_price > 0 THEN (exit_price - entry_price) / entry_price * 100 END AS move_pct, CASE WHEN entry_price > stop_loss THEN (take_profit - entry_price) / (entry_price - stop_loss) END AS planned_rr FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) ORDER BY closed_at DESC LIMIT 6